
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_revm06_l_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_revm06_l", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.829518701801407e+00, -4.763935231031049e+00, -4.666889857387772e+00, -4.522076599588659e+00, -4.304945190654778e+00, -3.982344738188416e+00, -3.521778011005104e+00, -2.914947801139950e+00, -2.201951550299797e+00, -1.492078738722669e+00, -7.885355585597917e-01, -5.710022334582222e-01, -6.342317122434172e-01, -5.346419299443155e-01, -3.576901277617685e-01, -1.815442514106365e-01, -4.975085884714658e-02, -2.028092020264377e-02, -4.790240221264837e-03, -5.412333829979352e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


